sql.20261230060000_rpc_kontrola_opravneni.sq:
-- Bug: tri SECURITY DEFINER RPC funkce menily data bez kontroly
-- user_can_edit_module, i kdyz kazda prima uprava tychz tabulek pres RLS
-- tuhle kontrolu ma (viz 20261128000000_enforce_module_edit_permissions.sql
-- a 20261204000000_enforce_module_permissions_remaining.sql). Funkce navic
-- volaji primo z klienta (src/lib/tankFrontaBeh.ts, src/lib/zavozSync.ts,
-- src/screens/Orders.tsx, src/components/OrderAuditModal.tsx), ne jen
-- interne z jine funkce - takze prihlaseny uzivatel BEZ prava na modul
-- Sklep/Objednavky mohl timhle bocnim vchodem menit objem tanku nebo
-- prepisovat odpocty ze zavozu, i kdyz mu appka i RLS na primych tabulkach
-- tohle jinak zamykaji.
--
-- Oprava: stejna kontrola jako u odpovidajicich RLS politik, jen presunuta
-- dovnitr funkci. Zbytek logiky (idempotence, uzky rozsah zmeny) beze zmeny.

CREATE OR REPLACE FUNCTION public.adjust_tank_volume_once(
  p_tank_id uuid,
  p_delta_l numeric,
  p_klic text,
  p_zdroj text DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF NOT public.user_can_edit_module('cellar') THEN
    RAISE EXCEPTION 'Nemas opravneni upravovat Sklep';
  END IF;
  IF p_klic IS NULL OR length(p_klic) < 8 THEN
    RAISE EXCEPTION 'Chybi klic idempotence';
  END IF;
  IF p_tank_id IS NULL OR p_delta_l IS NULL OR p_delta_l = 0 THEN
    RETURN 'nic';
  END IF;

  BEGIN
    INSERT INTO public.tank_uprava_log (klic, tank_id, delta_l, zdroj)
    VALUES (p_klic, p_tank_id, p_delta_l, p_zdroj);
  EXCEPTION WHEN unique_violation THEN
    RETURN 'jiz_provedeno';
  END;

  PERFORM public.adjust_tank_volume(p_tank_id, p_delta_l);
  RETURN 'provedeno';
END;
$$;

CREATE OR REPLACE FUNCTION public.smaz_odpocty_polozky(p_order_item_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF NOT (public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz')) THEN
    RAISE EXCEPTION 'Nemas opravneni upravovat objednavky';
  END IF;
  IF p_order_item_id IS NULL THEN
    RETURN;
  END IF;

  DELETE FROM public.zavoz_deductions WHERE order_item_id = p_order_item_id;
END
$$;

CREATE OR REPLACE FUNCTION public.reconcile_zavoz_deduction_for_item(
  p_order_item_id uuid,
  p_beer_id uuid,
  p_package_id uuid,
  p_quantity numeric
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF NOT (public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz')) THEN
    RAISE EXCEPTION 'Nemas opravneni upravovat objednavky';
  END IF;
  IF p_order_item_id IS NULL OR p_quantity IS NULL OR p_quantity <= 0 THEN
    RETURN;
  END IF;

  UPDATE public.zavoz_deductions
  SET beer_id = p_beer_id,
      package_id = p_package_id,
      quantity = p_quantity,
      note = trim(both ' ' from COALESCE(note, 'Automaticky odpocet zavozu') || ' (upraveno po zavozu)')
  WHERE order_item_id = p_order_item_id
    AND (beer_id IS DISTINCT FROM p_beer_id
      OR package_id IS DISTINCT FROM p_package_id
      OR quantity IS DISTINCT FROM p_quantity);
END
$$;

REVOKE ALL ON FUNCTION public.adjust_tank_volume_once(uuid, numeric, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.adjust_tank_volume_once(uuid, numeric, text, text) TO authenticated;
REVOKE ALL ON FUNCTION public.smaz_odpocty_polozky(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.smaz_odpocty_polozky(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.reconcile_zavoz_deduction_for_item(uuid, uuid, uuid, numeric) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reconcile_zavoz_deduction_for_item(uuid, uuid, uuid, numeric) TO authenticated;

sql.20261230070000_push_odbery_a_chyby_uzsi_:
-- Dve drobne zpresneni prav, obe nalezene pri auditu 13. 9. 2026.
--
-- 1) push_odbery: UPDATE/DELETE bylo otevrene komukoli prihlasenemu, i kdyz
-- tabulka ma sloupec user_id primo pro rozliseni vlastnika. Kdokoli mohl
-- smazat/prepsat cizi odber push upozorneni. Klient (src/lib/pushOdber.ts)
-- teď pri prihlaseni k odberu posila user_id vyslovne (misto spolehnuti na
-- DB vychozi hodnotu jen pri INSERTu) — na sdilenem zarizeni se tak
-- vlastnictvi radku pri prihlaseni dalsiho cloveka spravne prepise na nej,
-- takze omezeni na vlastnika nerozbije bezny provoz.
DROP POLICY IF EXISTS "auth_write_push_odbery" ON public.push_odbery;
CREATE POLICY "auth_write_push_odbery" ON public.push_odbery
  FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());

DROP POLICY IF EXISTS "auth_update_push_odbery" ON public.push_odbery;
CREATE POLICY "auth_update_push_odbery" ON public.push_odbery
  FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

DROP POLICY IF EXISTS "auth_delete_push_odbery" ON public.push_odbery;
CREATE POLICY "auth_delete_push_odbery" ON public.push_odbery
  FOR DELETE TO authenticated USING (user_id = auth.uid());

-- 2) app_errors: UPDATE bylo otevrene na vsechny sloupce, ale jedine pouziti
-- v appce je odklepnuti "vyrizeno" (AdminDiagnostika). Kdokoli prihlaseny
-- mohl primym REST volanim prepsat text/stack cizi chyby. RLS radek pusti
-- dal (to zustava — cist a odklepavat smi kazdy), sloupcove opravneni navic
-- omezi, CO smi UPDATE menit.
REVOKE UPDATE ON public.app_errors FROM authenticated;
GRANT UPDATE (vyrizeno_at) ON public.app_errors TO authenticated;

sql.20261231030000_ranni_souhrn_sudy_stk_a_t:
-- 🔔 Ranní souhrn umí víc + středeční upozornění na mlčící odběratele.
--
-- Návrhy z 13. 9. 2026 (páté kolo), body 12 a 13:
--
--  • Ranní souhrn dosud hlásil jen čekající WhatsApp zprávy a výčepy po
--    termínu. Přibývá:
--      – končící nebo prošlá STK a dálniční známka (stejný práh 30 dní jako
--        lib/vozidla.ts — do teď to viděl jen ten, kdo otevřel Domů),
--      – sudy dlouho u odběratele (stejné pravidlo jako lib/sudyVenku.ts:
--        nevrácené sudy a od posledního vrácení, případně prvního odvozu,
--        uplynulo aspoň 30 dní).
--    „Docházející zboží" se do souhrnu záměrně NEPŘIDÁVÁ: stav skladu počítá
--    skladová kniha v aplikaci (lib/stockLedger.ts) z dvanácti tabulek a
--    druhá kopie téhož výpočtu v SQL by se od ní dřív nebo později rozešla.
--
--  • Pravidelný odběratel, který mlčí déle, než je u něj obvyklé. Seznam
--    existuje v kontrole objednávek (lib/kontrolaObjednavek.ts,
--    tichoUOdberatelu), ale vidí ho jen ten, kdo tu kontrolu otevře. Push jde
--    ve středu ráno — ještě je čas zavolat před čtvrtečním a pátečním
--    závozem. Pravidlo je stejné: aspoň 4 zprávy za poslední 3 měsíce,
--    ticho delší než 2,5× medián odstupů a zároveň aspoň 7 dní.

CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;

CREATE OR REPLACE FUNCTION public.posli_ranni_souhrn()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_secret text;
  v_whatsapp_cekajici int;
  v_vycepy_po_terminu int;
  v_kauce_czk numeric;
  v_vozidla int;
  v_vozidla_nazvy text;
  v_sudy_mist int;
  v_sudy_kusu int;
  v_radky text[] := ARRAY[]::text[];
  v_stranka text;
BEGIN
  SELECT value INTO v_secret FROM app_secrets WHERE key = 'WHATSAPP_CRON_SECRET';
  IF v_secret IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_whatsapp_cekajici
  FROM whatsapp_incoming
  WHERE status IN ('pending', 'parsed', 'error');

  SELECT count(*), coalesce(sum(kauce_czk), 0)
  INTO v_vycepy_po_terminu, v_kauce_czk
  FROM vycepy_rezervace
  WHERE vraceno = false
    AND coalesce(datum_do, datum_od) <= current_date - interval '2 days';

  SELECT count(*), string_agg(coalesce(nullif(spz, ''), name), ', ' ORDER BY name)
  INTO v_vozidla, v_vozidla_nazvy
  FROM vehicles
  WHERE (stk_valid_until IS NOT NULL AND stk_valid_until <= current_date + 30)
     OR (highway_toll_valid_until IS NOT NULL AND highway_toll_valid_until <= current_date + 30);

  WITH konto AS (
    SELECT
      coalesce(place_id::text, 'name:' || lower(coalesce(place_name, ''))) AS klic,
      sum(CASE WHEN direction = 'out' THEN quantity ELSE -quantity END) AS pocet,
      max(entry_date) FILTER (WHERE direction = 'in') AS posledni_vraceni,
      min(entry_date) FILTER (WHERE direction = 'out') AS prvni_odvoz
    FROM keg_returns
    GROUP BY 1
  )
  SELECT count(*), coalesce(sum(pocet), 0)
  INTO v_sudy_mist, v_sudy_kusu
  FROM konto
  WHERE klic <> 'name:'
    AND pocet > 0
    AND current_date - coalesce(posledni_vraceni, prvni_odvoz) >= 30;

  IF v_whatsapp_cekajici = 0 AND v_vycepy_po_terminu = 0 AND v_vozidla = 0 AND v_sudy_mist = 0 THEN
    RETURN;
  END IF;

  IF v_whatsapp_cekajici > 0 THEN
    v_radky := v_radky || (v_whatsapp_cekajici::text || 'x WhatsApp objednávka čeká na schválení');
    v_stranka := coalesce(v_stranka, 'orders');
  END IF;
  IF v_vycepy_po_terminu > 0 THEN
    v_radky := v_radky || (v_vycepy_po_terminu::text || 'x výčep po termínu (kauce ' || v_kauce_czk::text || ' Kč)');
    v_stranka := coalesce(v_stranka, 'vycepy');
  END IF;
  IF v_sudy_mist > 0 THEN
    v_radky := v_radky || (v_sudy_kusu::text || ' sudů leží přes 30 dní u ' || v_sudy_mist::text || ' odběratelů');
    v_stranka := coalesce(v_stranka, 'zavoz');
  END IF;
  IF v_vozidla > 0 THEN
    v_radky := v_radky || ('STK nebo dálniční známka končí: ' || v_vozidla_nazvy);
    v_stranka := coalesce(v_stranka, 'catalogs');
  END IF;

  PERFORM net.http_post(
    url := 'https://sasqexjadvlqyticxwja.supabase.co/functions/v1/posli-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Internal-Cron-Secret', v_secret
    ),
    body := jsonb_build_object(
      'titulek', 'Ranní souhrn',
      'telo', array_to_string(v_radky, ' · '),
      'stranka', v_stranka,
      'tag', 'ranni-souhrn'
    )
  );
END;
$$;

COMMENT ON FUNCTION public.posli_ranni_souhrn() IS
  'Denní push: WhatsApp čeká na schválení, výčepy po termínu, sudy přes 30 dní u odběratele, končící STK/známka. Viz docs/20-navrhu-2026-09-13.md body 12-13.';

CREATE OR REPLACE FUNCTION public.posli_tydenni_ticho()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_secret text;
  v_pocet int;
  v_jmena text;
BEGIN
  SELECT value INTO v_secret FROM app_secrets WHERE key = 'WHATSAPP_CRON_SECRET';
  IF v_secret IS NULL THEN
    RETURN;
  END IF;

  WITH zpravy AS (
    SELECT trim(sender_name) AS kdo, created_at
    FROM whatsapp_incoming
    WHERE coalesce(trim(sender_name), '') <> ''
      AND created_at >= now() - interval '3 months'
  ),
  odstupy AS (
    SELECT kdo, created_at,
      extract(epoch FROM created_at - lag(created_at) OVER (PARTITION BY kdo ORDER BY created_at)) / 86400 AS odstup
    FROM zpravy
  ),
  rytmus AS (
    SELECT kdo,
      count(*) AS pocet,
      percentile_cont(0.5) WITHIN GROUP (ORDER BY odstup) FILTER (WHERE odstup IS NOT NULL) AS obvykle,
      max(created_at) AS posledni
    FROM odstupy
    GROUP BY kdo
  ),
  mlci AS (
    SELECT kdo, extract(epoch FROM now() - posledni) / 86400 / obvykle AS pomer
    FROM rytmus
    WHERE pocet >= 4
      AND obvykle > 0
      AND extract(epoch FROM now() - posledni) / 86400 >= greatest(7, obvykle * 2.5)
  )
  SELECT count(*), string_agg(kdo, ', ' ORDER BY pomer DESC)
  INTO v_pocet, v_jmena
  FROM mlci;

  IF v_pocet = 0 THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := 'https://sasqexjadvlqyticxwja.supabase.co/functions/v1/posli-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Internal-Cron-Secret', v_secret
    ),
    body := jsonb_build_object(
      'titulek', 'Odběratelé se neozvali',
      'telo', v_pocet::text || ' pravidelných odběratelů mlčí déle než obvykle: ' || v_jmena,
      'stranka', 'orders',
      'tag', 'tydenni-ticho'
    )
  );
END;
$$;

COMMENT ON FUNCTION public.posli_tydenni_ticho() IS
  'Středeční push: pravidelní odběratelé, kteří mlčí déle než 2,5× obvyklý odstup (stejně jako lib/kontrolaObjednavek.ts tichoUOdberatelu).';

-- Středa 5:00 UTC = 7:00 v létě, 6:00 v zimě (stejný kompromis jako ranní souhrn).
SELECT cron.schedule(
  'tydenni-ticho-push',
  '0 5 * * 3',
  $$SELECT public.posli_tydenni_ticho();$$
);

-- Volat smí jen plánovač (běží jako vlastník), ne přihlášený uživatel.
REVOKE ALL ON FUNCTION public.posli_ranni_souhrn() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.posli_tydenni_ticho() FROM PUBLIC, anon, authenticated;

sql.20261231040000_historie_zmen_cen.sql:
-- 💰 Historie změn cen.
--
-- Návrh z 13. 9. 2026 (páté kolo), bod 20. Ceník (obrazovka Ceník) přepisuje
-- cenu na místě: cena za litr sudového piva je sloupec beers.price_per_liter
-- a cena lahve se v price_list aktualizuje UPDATEm. Po změně tak nikde
-- nezůstalo, kolik to stálo předtím a kdy se zdražilo — přesně to, na co se
-- odběratel ptá.
--
-- Zápis dělají triggery, ne obrazovka: cenu jde změnit i jinudy (import,
-- ruční zásah v Supabase) a historie, která zná jen jednu cestu, by lhala.

CREATE TABLE IF NOT EXISTS public.cenik_zmeny (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  druh text NOT NULL CHECK (druh IN ('litr', 'kus')),
  beer_id uuid REFERENCES public.beers(id) ON DELETE SET NULL,
  package_id uuid REFERENCES public.packages(id) ON DELETE SET NULL,
  stara_cena numeric,
  nova_cena numeric,
  zmenil uuid DEFAULT auth.uid()
);

CREATE INDEX IF NOT EXISTS cenik_zmeny_created_idx ON public.cenik_zmeny (created_at DESC);

ALTER TABLE public.cenik_zmeny ENABLE ROW LEVEL SECURITY;

-- Číst smí každý přihlášený (ceník vidí všichni). Zapisují jen triggery níž
-- (SECURITY DEFINER) — ruční INSERT/UPDATE/DELETE z aplikace nejde, aby se
-- historie nedala přepsat.
DROP POLICY IF EXISTS cenik_zmeny_select ON public.cenik_zmeny;
CREATE POLICY cenik_zmeny_select ON public.cenik_zmeny
  FOR SELECT TO authenticated USING (true);

CREATE OR REPLACE FUNCTION public.zapis_zmenu_ceny_piva()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.price_per_liter IS DISTINCT FROM OLD.price_per_liter THEN
    INSERT INTO public.cenik_zmeny (druh, beer_id, stara_cena, nova_cena)
    VALUES ('litr', NEW.id, OLD.price_per_liter, NEW.price_per_liter);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS beers_zmena_ceny ON public.beers;
CREATE TRIGGER beers_zmena_ceny
  AFTER UPDATE OF price_per_liter ON public.beers
  FOR EACH ROW EXECUTE FUNCTION public.zapis_zmenu_ceny_piva();

CREATE OR REPLACE FUNCTION public.zapis_zmenu_ceny_lahve()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
    VALUES ('kus', NEW.beer_id, NEW.package_id, NULL, NEW.price_per_unit);
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.price_per_unit IS DISTINCT FROM OLD.price_per_unit THEN
      INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
      VALUES ('kus', NEW.beer_id, NEW.package_id, OLD.price_per_unit, NEW.price_per_unit);
    END IF;
    RETURN NEW;
  ELSE
    INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
    VALUES ('kus', OLD.beer_id, OLD.package_id, OLD.price_per_unit, NULL);
    RETURN OLD;
  END IF;
END;
$$;

DROP TRIGGER IF EXISTS price_list_zmena_ceny ON public.price_list;
CREATE TRIGGER price_list_zmena_ceny
  AFTER INSERT OR UPDATE OF price_per_unit OR DELETE ON public.price_list
  FOR EACH ROW EXECUTE FUNCTION public.zapis_zmenu_ceny_lahve();

REVOKE ALL ON FUNCTION public.zapis_zmenu_ceny_piva() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.zapis_zmenu_ceny_lahve() FROM PUBLIC, anon, authenticated;

-- Realtime, ať se nový záznam v historii ukáže bez obnovení stránky.
DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cenik_zmeny;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

sql.20261231050000_varky_mereni_a_kvasnice.s:
-- 🧪 Várky ve sklepě: průběh kvašení a generace kvasnic.
--
-- Návrhy z 13. 9. 2026 (páté kolo), body 9 a 11. Tabulka cellar_batches
-- existuje od srpna 2026, ale žádná obrazovka do ní nepsala (komentář
-- u tabulky to přiznává: „legacy — doposud žádný kód nepíše"). Várka měla
-- jen počáteční a konečnou stupňovitost, takže průběh kvašení se nikde
-- nezapisoval, a generaci kvasnic appka neznala vůbec.

ALTER TABLE public.cellar_batches
  ADD COLUMN IF NOT EXISTS kvasnice_generace integer,
  ADD COLUMN IF NOT EXISTS kvasnice_z_varky uuid REFERENCES public.cellar_batches(id) ON DELETE SET NULL;

ALTER TABLE public.cellar_batches DROP CONSTRAINT IF EXISTS cellar_batches_generace_kladna;
ALTER TABLE public.cellar_batches
  ADD CONSTRAINT cellar_batches_generace_kladna CHECK (kvasnice_generace IS NULL OR kvasnice_generace >= 1);

COMMENT ON TABLE public.cellar_batches IS
  'Várky v tancích sklepa. Zapisuje obrazovka Sklep → Várky (components/VarkySklep.tsx).';
COMMENT ON COLUMN public.cellar_batches.kvasnice_generace IS
  'Kolikátá generace kvasnic (1 = čerstvé). Při nasazení z jiné várky appka navrhne generaci o jedna vyšší.';

CREATE TABLE IF NOT EXISTS public.cellar_batch_mereni (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  batch_id uuid NOT NULL REFERENCES public.cellar_batches(id) ON DELETE CASCADE,
  measured_at timestamptz NOT NULL DEFAULT now(),
  stupnovitost numeric,
  teplota_c numeric,
  poznamka text,
  zapsal text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT cellar_batch_mereni_neco_namereno CHECK (stupnovitost IS NOT NULL OR teplota_c IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS cellar_batch_mereni_batch_idx ON public.cellar_batch_mereni (batch_id, measured_at);

ALTER TABLE public.cellar_batch_mereni ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS cellar_batch_mereni_select ON public.cellar_batch_mereni;
CREATE POLICY cellar_batch_mereni_select ON public.cellar_batch_mereni
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS perm_insert_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_insert_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR INSERT TO authenticated WITH CHECK (public.user_can_edit_module('cellar'));

DROP POLICY IF EXISTS perm_update_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_update_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('cellar'))
  WITH CHECK (public.user_can_edit_module('cellar'));

DROP POLICY IF EXISTS perm_delete_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_delete_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR DELETE TO authenticated USING (public.user_can_edit_module('cellar'));

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cellar_batches;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cellar_batch_mereni;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

sql.20261231090000_zavreny_mesic.sql:
-- "Zavřít měsíc" — tvrdý zámek na objednávky a všechny zápisy výroby/skladu
-- za daný měsíc. Bez tohohle šlo do dávno napočítaného a dorovnaného měsíce
-- dopsat cokoliv a schodek se pak hledal jako záhada (viz komentář u
-- lib/mesicUzamcen.ts — to je jen NEVYNUCENÉ upozornění, appka zápisu
-- nezabrání).
--
-- Z provozu 14. 9. 2026: "udělej, když dám zavřít měsíc, ať už nemůže nic
-- a nikdo sahat do objednávek a stáčení, jen budou k nahlížení, upravit je
-- může jen admin".
--
-- ROZSAH ZÁMKU: všechno, co mění sklad za ten měsíc — objednávky
-- (orders/order_items), stáčení (kegging), lahvování (bottling), fasování
-- (fasovani/fasovani_private), odpisy (writeoffs) a akce (akce/akce_items).
-- NE inventura samotná (inventory/inventory_adjustments) — do napočítaného
-- měsíce se právě TAM dopisuje dorovnání, kterým se měsíc uzavírá.
--
-- ODEMČENÍ: podle přihlášené role, ŽÁDNÉ zvláštní heslo navíc — appka už
-- rozlišuje role (admin/šéf/sládek/manažer, viz lib/permissions.ts,
-- canUserEdit) a přesně tahle sada rolí už dnes obchází omezení modulů
-- (user_can_edit_module() → `IF v_role = 'admin' THEN RETURN true`). Zámek
-- měsíce je stejná myšlenka, jen navíc kontroluje i sládka/šéfa/manažera —
-- ti sice per-modul omezení nemívají, ale i pro ně platí, že do uzavřeného
-- měsíce se má sahat jen vědomě.
--
-- PROČ FUNKCE, NE JEN SLOUPEC is_closed NA orders/kegging/...: měsíc se
-- zavírá JEDNOU na jednom místě (tabulka closed_months), ne opakovaně na
-- každé tabulce zvlášť — a nová objednávka/zápis v UŽ zavřeném měsíci
-- (výjimečně, admin) nemusí měnit nic jinde.

CREATE TABLE IF NOT EXISTS public.closed_months (
  month text PRIMARY KEY, -- 'YYYY-MM'
  closed_at timestamptz NOT NULL DEFAULT now(),
  closed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL
);

COMMENT ON TABLE public.closed_months IS
  'Měsíce uzavřené v Inventuře. Existence řádku = objednávky a zápisy výroby/skladu za ten měsíc jsou pro běžné role jen ke čtení (viz smi_zapisovat_pro_datum).';

ALTER TABLE public.closed_months ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "auth_read_closed_months" ON public.closed_months;
CREATE POLICY "auth_read_closed_months" ON public.closed_months
  FOR SELECT TO authenticated USING (true);

-- Zavřít i znovu otevřít měsíc smí jen admin/šéf/sládek/manažer — je to
-- rozhodnutí o účetní uzávěrce, ne běžný provozní zápis.
CREATE OR REPLACE FUNCTION public.is_admin_tier_role()
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN true; -- service_role / trigger kontext, ne appka
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  RETURN v_role IN ('admin', 'sef', 'sladek', 'boss', 'manager');
EXCEPTION WHEN OTHERS THEN
  RETURN true; -- fail-open, stejný vzor jako user_can_edit_module()
END;
$$;

DROP POLICY IF EXISTS "admin_insert_closed_months" ON public.closed_months;
CREATE POLICY "admin_insert_closed_months" ON public.closed_months
  FOR INSERT TO authenticated WITH CHECK (public.is_admin_tier_role());
DROP POLICY IF EXISTS "admin_delete_closed_months" ON public.closed_months;
CREATE POLICY "admin_delete_closed_months" ON public.closed_months
  FOR DELETE TO authenticated USING (public.is_admin_tier_role());

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.closed_months;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'closed_months už v publikaci: %', SQLERRM;
END $$;

-- Patří datum do uzavřeného měsíce?
CREATE OR REPLACE FUNCTION public.mesic_je_uzavren(p_datum date)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT p_datum IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.closed_months WHERE month = to_char(p_datum, 'YYYY-MM')
  );
$$;

-- Smí se zapisovat k tomuhle datu? Ano, pokud měsíc není zavřený, nebo je
-- zavřený ale píše admin/šéf/sládek/manažer. Chybějící datum (NULL) NEBLOKUJE
-- — radši nechat projít, než appku zaseknout na řádku bez data, který zámek
-- stejně nemá jak posoudit.
CREATE OR REPLACE FUNCTION public.smi_zapisovat_pro_datum(p_datum date)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT p_datum IS NULL
      OR NOT public.mesic_je_uzavren(p_datum)
      OR public.is_admin_tier_role();
$$;

-- ===== Objednávky (orders/order_items) =====
-- Rozhodné datum je den závozu (delivery_date), a když není zadaný, den
-- zadání objednávky — stejná dvojice, jakou appka zobrazuje jako "kdy se to
-- řeší". Přesný přepočet na den v týdnu (viz process_zavoz_deductions_for_date)
-- by tu byl zbytečně složitý, zámek je jen hrubá ochrana proti zápisu do
-- starého měsíce, ne přesný plánovač.
DROP POLICY IF EXISTS "perm_insert_orders" ON public.orders;
CREATE POLICY "perm_insert_orders" ON public.orders FOR INSERT TO authenticated
  WITH CHECK ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND public.smi_zapisovat_pro_datum(COALESCE(delivery_date, order_date)));
DROP POLICY IF EXISTS "perm_update_orders" ON public.orders;
CREATE POLICY "perm_update_orders" ON public.orders FOR UPDATE TO authenticated
  USING ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND public.smi_zapisovat_pro_datum(COALESCE(delivery_date, order_date)))
  WITH CHECK ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND public.smi_zapisovat_pro_datum(COALESCE(delivery_date, order_date)));
DROP POLICY IF EXISTS "perm_delete_orders" ON public.orders;
CREATE POLICY "perm_delete_orders" ON public.orders FOR DELETE TO authenticated
  USING ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND public.smi_zapisovat_pro_datum(COALESCE(delivery_date, order_date)));

-- order_items nemá vlastní datum — bere ho z rodičovské objednávky.
DROP POLICY IF EXISTS "perm_insert_order_items" ON public.order_items;
CREATE POLICY "perm_insert_order_items" ON public.order_items FOR INSERT TO authenticated
  WITH CHECK ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND COALESCE((SELECT public.smi_zapisovat_pro_datum(COALESCE(o.delivery_date, o.order_date))
                  FROM public.orders o WHERE o.id = order_id), true));
DROP POLICY IF EXISTS "perm_update_order_items" ON public.order_items;
CREATE POLICY "perm_update_order_items" ON public.order_items FOR UPDATE TO authenticated
  USING ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND COALESCE((SELECT public.smi_zapisovat_pro_datum(COALESCE(o.delivery_date, o.order_date))
                  FROM public.orders o WHERE o.id = order_id), true))
  WITH CHECK ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND COALESCE((SELECT public.smi_zapisovat_pro_datum(COALESCE(o.delivery_date, o.order_date))
                  FROM public.orders o WHERE o.id = order_id), true));
DROP POLICY IF EXISTS "perm_delete_order_items" ON public.order_items;
CREATE POLICY "perm_delete_order_items" ON public.order_items FOR DELETE TO authenticated
  USING ((public.user_can_edit_module('orders') OR public.user_can_edit_module('zavoz'))
    AND COALESCE((SELECT public.smi_zapisovat_pro_datum(COALESCE(o.delivery_date, o.order_date))
                  FROM public.orders o WHERE o.id = order_id), true));

-- ===== Stáčení (kegging) =====
DROP POLICY IF EXISTS "auth_write_kegging" ON public.kegging;
DROP POLICY IF EXISTS "perm_insert_kegging" ON public.kegging;
CREATE POLICY "perm_insert_kegging" ON public.kegging FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('kegging') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "auth_update_kegging" ON public.kegging;
DROP POLICY IF EXISTS "perm_update_kegging" ON public.kegging;
CREATE POLICY "perm_update_kegging" ON public.kegging FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('kegging') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('kegging') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "auth_delete_kegging" ON public.kegging;
DROP POLICY IF EXISTS "perm_delete_kegging" ON public.kegging;
CREATE POLICY "perm_delete_kegging" ON public.kegging FOR DELETE TO authenticated
  USING (public.user_can_edit_module('kegging') AND public.smi_zapisovat_pro_datum(entry_date));

-- ===== Výroba (bottling, fasovani, fasovani_private, writeoffs — modul "entry") =====
DROP POLICY IF EXISTS "perm_insert_bottling" ON public.bottling;
CREATE POLICY "perm_insert_bottling" ON public.bottling FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_update_bottling" ON public.bottling;
CREATE POLICY "perm_update_bottling" ON public.bottling FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_delete_bottling" ON public.bottling;
CREATE POLICY "perm_delete_bottling" ON public.bottling FOR DELETE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));

DROP POLICY IF EXISTS "perm_insert_fasovani" ON public.fasovani;
CREATE POLICY "perm_insert_fasovani" ON public.fasovani FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_update_fasovani" ON public.fasovani;
CREATE POLICY "perm_update_fasovani" ON public.fasovani FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_delete_fasovani" ON public.fasovani;
CREATE POLICY "perm_delete_fasovani" ON public.fasovani FOR DELETE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));

DROP POLICY IF EXISTS "perm_insert_fasovani_private" ON public.fasovani_private;
CREATE POLICY "perm_insert_fasovani_private" ON public.fasovani_private FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_update_fasovani_private" ON public.fasovani_private;
CREATE POLICY "perm_update_fasovani_private" ON public.fasovani_private FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_delete_fasovani_private" ON public.fasovani_private;
CREATE POLICY "perm_delete_fasovani_private" ON public.fasovani_private FOR DELETE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));

DROP POLICY IF EXISTS "perm_insert_writeoffs" ON public.writeoffs;
CREATE POLICY "perm_insert_writeoffs" ON public.writeoffs FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_update_writeoffs" ON public.writeoffs;
CREATE POLICY "perm_update_writeoffs" ON public.writeoffs FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_delete_writeoffs" ON public.writeoffs;
CREATE POLICY "perm_delete_writeoffs" ON public.writeoffs FOR DELETE TO authenticated
  USING (public.user_can_edit_module('entry') AND public.smi_zapisovat_pro_datum(entry_date));

-- ===== Akce (akce/akce_items) =====
DROP POLICY IF EXISTS "perm_insert_akce" ON public.akce;
CREATE POLICY "perm_insert_akce" ON public.akce FOR INSERT TO authenticated
  WITH CHECK (public.user_can_edit_module('akce') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_update_akce" ON public.akce;
CREATE POLICY "perm_update_akce" ON public.akce FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('akce') AND public.smi_zapisovat_pro_datum(entry_date))
  WITH CHECK (public.user_can_edit_module('akce') AND public.smi_zapisovat_pro_datum(entry_date));
DROP POLICY IF EXISTS "perm_delete_akce" ON public.akce;
CREATE POLICY "perm_delete_akce" ON public.akce FOR DELETE TO authenticated
  USING (public.user_can_edit_module('akce') AND public.smi_zapisovat_pro_datum(entry_date));

DROP POLICY IF EXISTS "perm_insert_akce_items" ON public.akce_items;
